export type StatKey = "audace" | "lucidite" | "sangFroid" | "resonance";
export type PeriodKey = "aube" | "matin" | "apres-midi" | "soirée";

export type DialogueLine = { speaker: string; text: string; mood?: string };
export type Effects = {
  stats?: Partial<Record<StatKey, number>>;
  affection?: number;
  trust?: number;
  desire?: number;
  confluence?: number;
  coins?: number;
  items?: Record<string, number>;
  flags?: string[];
  knowledge?: string[];
  relationshipEffects?: Record<string, Partial<Pick<Effects, "affection" | "trust" | "desire">>>;
};

export type ChoiceData = {
  id: string;
  text: string;
  playerLine?: string;
  stat: StatKey;
  response: DialogueLine[];
  effects: Effects;
  requires?: { stat: StatKey; value: number };
  requiresRelationship?: { character: string; stage?: number; trust?: number; affection?: number }[];
  requiresKnowledge?: string[];
  dateOutcome?: "great" | "good" | "awkward";
};

export type RouteScene = {
  id: string;
  character: string;
  stage: number;
  dayMin: number;
  title: string;
  location: string;
  background: string;
  mood: string;
  intro: DialogueLine[];
  choices: ChoiceData[];
  intimate?: boolean;
};

export type CharacterData = {
  id: string;
  name: string;
  role: string;
  ageNote: string;
  portrait: string;
  color: string;
  unlockDay: number;
  defaultMood: string;
  tagline: string;
  bio: string;
  wound: string;
  appreciates: string;
  giftLikes: string[];
  itinerary: ItineraryStop[];
};

export type ItineraryStop = {
  days: number;
  location?: string;
  travelTo?: string;
  note: string;
};

export type LocationData = {
  id: string;
  name: string;
  subtitle: string;
  image: string;
  background: string;
  unlockDay: number;
  pin: [number, number];
  description: string;
  activities: string[];
  minor?: boolean;
};

export type GiftData = {
  id: string;
  name: string;
  description: string;
  price: number;
  icon: string;
};

const line = (speaker: string, text: string): DialogueLine => ({ speaker, text });
const choice = (
  id: string,
  text: string,
  stat: StatKey,
  response: DialogueLine[],
  effects: Effects,
  requires?: ChoiceData["requires"],
): ChoiceData => ({ id, text, stat, response, effects, requires });
const routeScene = (
  character: string,
  stage: number,
  dayMin: number,
  title: string,
  location: string,
  background: string,
  mood: string,
  intro: DialogueLine[],
  choices: ChoiceData[],
  intimate = false,
): RouteScene => ({ id: `${character}-${stage}`, character, stage, dayMin, title, location, background, mood, intro, choices, intimate });

